use std::{fs,path::Path,collections::BTreeMap};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-g2-tree-c7a";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new(R);let mut pins=BTreeMap::new();let mut steps=Vec::new();let mut env=Value::Null;
 for(name,old)in[("baseline","/tmp/zopro-g2-level-tree"),("candidate","/tmp/zopro-g2-prefix-tree")]{let old=Path::new(old);let source=r.join(format!("{name}-source"));let oldpins=read(old.join("source-pins.json"));for(p,h)in oldpins.as_object().unwrap(){let prefix=old.join("candidate");if let Ok(rel)=Path::new(p).strip_prefix(&prefix){let new=source.join(rel);assert_eq!(hash(&new),h.as_str().unwrap(),"source changed: {}",new.display());pins.insert(new.display().to_string(),hash(new));}}
  let oldplan=read(old.join("native-plan.json"));if env.is_null(){env=oldplan["environment"].clone();}for step in oldplan["steps"].as_array().unwrap(){if step["name"]=="compiler"{if name=="baseline"{steps.push(step.clone());}continue;}let mut s=step.clone();let text=serde_json::to_string(&s).unwrap().replace(&old.join("candidate").display().to_string(),&source.display().to_string()).replace(&old.join("target-sdk-on").display().to_string(),&r.join(format!("target-{name}")).display().to_string()).replace(&old.join("native/on-libraries").display().to_string(),&r.join(format!("native/{name}-libraries")).display().to_string()).replace("target-cpu=native","target-cpu=znver4");s=serde_json::from_str(&text).unwrap();let original=s["name"].as_str().unwrap();s["name"]=json!(if original=="on"{name.to_owned()}else{format!("{name}-{}",original.strip_prefix("on-").unwrap_or(original))});if s["kind"]=="link-sdk"{s["driver"]=json!(r.join(format!("{name}-probe.rs")));s["additional_sources"]=json!([r.join("support/perf.rs")]);s["rustc_flags"]=json!(["-O","-C","target-cpu=znver4","-C","lto=off","-C","codegen-units=1"]);}steps.push(s);}
 }
 for rel in ["baseline-probe.rs","candidate-probe.rs","support/perf.rs","prepare-build.rs","design.md","runner.rs","prepare-image.rs"]{let p=r.join(rel);pins.insert(p.display().to_string(),hash(p));}
 let a=read("/tmp/zopro-ready-c7a/native/accepted-field/tests.json");assert_eq!(a["passed_tests"].as_array().unwrap().len(),33);let p="/tmp/zopro-ready-c7a/native/accepted-field/tests.json";pins.insert(p.into(),hash(p));
 save(r.join("build-pins.json"),&json!(pins));save(r.join("native-plan.json"),&json!({"version":1,"source_pins":r.join("build-pins.json"),"environment":env,"steps":steps}));println!("Pinned{}source/helperinputs; two byte-identical source snapshots targetznver4",pins.len());}
